begin;
-- No legal level/provider is inferred. Infrastructure owners provision a policy only after real approval.
create table private.contract_signature_policy_versions_v1(
 id uuid primary key default extensions.gen_random_uuid(),environment text not null check(environment in('DEVELOPMENT','STAGING','PRODUCTION')),
 source_kind text not null check(source_kind in('CONTRACT','AMENDMENT')),version integer not null check(version>0),provider_config_id uuid not null references public.signature_provider_configs(id),
 minimum_level text not null check(minimum_level in('SIMPLE','ADVANCED','QUALIFIED')),allow_development_mock boolean not null default false,
 require_certificate boolean not null default true,require_trusted_timestamp boolean not null default true,
 approval_reference text not null check(length(btrim(approval_reference))between 8 and 500),adapter_registration_reference text not null check(length(btrim(adapter_registration_reference))between 8 and 500),
 approved_by uuid not null references auth.users(id),reviewed_by uuid not null references auth.users(id),approved_at timestamptz not null,valid_until timestamptz,
 check(approved_by<>reviewed_by),check(valid_until is null or valid_until>approved_at),check(not allow_development_mock or(environment in('DEVELOPMENT','STAGING')and minimum_level='SIMPLE'and not require_certificate and not require_trusted_timestamp)),
 check(minimum_level='SIMPLE'or(require_certificate and require_trusted_timestamp)),unique(environment,source_kind,version)
);
create table private.contract_signature_source_artifacts_v1(
 id uuid primary key default extensions.gen_random_uuid(),source_kind text not null check(source_kind in('CONTRACT','AMENDMENT')),source_id uuid not null,
 contract_version_id uuid not null references public.contract_versions(id),source_hash text not null check(source_hash~'^[0-9a-f]{64}$'),parties_hash text not null check(parties_hash~'^[0-9a-f]{64}$'),
 pdf_sha256 text not null check(pdf_sha256~'^[0-9a-f]{64}$'),storage_object_id uuid not null unique references storage.objects(id),storage_path text not null,
 verified_at timestamptz not null,verification_reference text not null check(length(btrim(verification_reference))between 8 and 500),unique(source_kind,source_id,pdf_sha256)
);
alter table public.signature_envelopes add column amendment_id uuid references public.contract_amendments(id);
create table private.contract_signature_bindings_v1(
 envelope_id uuid primary key references public.signature_envelopes(id),policy_version_id uuid not null references private.contract_signature_policy_versions_v1(id),
 contract_version_id uuid not null references public.contract_versions(id),contract_version_hash text not null check(contract_version_hash~'^[0-9a-f]{64}$'),
 requested_level text not null check(requested_level in('SIMPLE','ADVANCED','QUALIFIED')),source_kind text not null check(source_kind in('CONTRACT','AMENDMENT')),source_id uuid not null,source_hash text not null check(source_hash~'^[0-9a-f]{64}$'),
 parties_hash text not null check(parties_hash~'^[0-9a-f]{64}$'),signers_hash text not null check(signers_hash~'^[0-9a-f]{64}$'),documents_hash text not null check(documents_hash~'^[0-9a-f]{64}$'),
 pdf_sha256 text not null check(pdf_sha256~'^[0-9a-f]{64}$'),source_artifact_id uuid references private.contract_signature_source_artifacts_v1(id),bound_at timestamptz not null default clock_timestamp()
);
alter table public.signature_evidence_packages add column source_binding_hash text check(source_binding_hash~'^[0-9a-f]{64}$');
revoke all on private.contract_signature_policy_versions_v1,private.contract_signature_source_artifacts_v1,private.contract_signature_bindings_v1 from public,anon,authenticated,service_role;
create trigger contract_signature_policy_immutable before update or delete on private.contract_signature_policy_versions_v1 for each row execute function private.prevent_contract_immutable_change();
create trigger contract_signature_sources_immutable before update or delete on private.contract_signature_source_artifacts_v1 for each row execute function private.prevent_contract_immutable_change();
create trigger contract_signature_bindings_immutable before update or delete on private.contract_signature_bindings_v1 for each row execute function private.prevent_contract_immutable_change();
create function private.contract_signature_parties_hash_v1(p_version_id uuid)returns text language sql stable security definer set search_path=pg_catalog,private as $$select private.canonical_request_hash(coalesce((select jsonb_agg(jsonb_build_object('organization_id',organization_id,'party_role',party_role,'legal_snapshot',legal_snapshot)order by party_role)from public.contract_parties where contract_version_id=p_version_id),'[]'))$$;
create function private.contract_signature_signers_hash_v1(p_envelope_id uuid)returns text language sql stable security definer set search_path=pg_catalog,private as $$select private.canonical_request_hash(coalesce((select jsonb_agg(jsonb_build_object('id',id,'organization_id',organization_id,'user_id',signer_user_id,'role',signer_role,'order',signing_order,'email_hash',email_hash)order by signing_order)from public.signature_signers where envelope_id=p_envelope_id),'[]'))$$;
create function private.contract_signature_documents_hash_v1(p_envelope_id uuid)returns text language sql stable security definer set search_path=pg_catalog,private as $$select private.canonical_request_hash(coalesce((select jsonb_agg(jsonb_build_object('version_id',contract_version_id,'kind',document_type,'version',exact_version,'sha256',sha256,'path',storage_path)order by sort_order)from public.signature_documents where envelope_id=p_envelope_id),'[]'))$$;
create function private.require_contract_signature_policy_v1(p_kind text)returns private.contract_signature_policy_versions_v1 language plpgsql stable security definer set search_path=pg_catalog,private as $$
declare env text;p private.contract_signature_policy_versions_v1%rowtype;cfg public.signature_provider_configs%rowtype;begin
 select environment into env from private.admin_execution_environment_v1 where singleton;
 if env is null then raise exception'SIGNATURE_DEPLOYMENT_ENVIRONMENT_UNCONFIGURED'using errcode='55000';end if;
 select*into p from private.contract_signature_policy_versions_v1 where environment=env and source_kind=p_kind and approved_at<=statement_timestamp()and(valid_until is null or valid_until>statement_timestamp())order by version desc limit 1;
 if p.id is null then raise exception'SIGNATURE_PROVIDER_NOT_CONFIGURED'using errcode='55000';end if;
 select*into cfg from public.signature_provider_configs where id=p.provider_config_id;
 perform private.require_signature_environment_v1(env,cfg.provider_code);
 if cfg.environment is distinct from env or cfg.status<>'ACTIVE'or cfg.valid_from>statement_timestamp()or cfg.valid_until<=statement_timestamp()or not(p.minimum_level=any(cfg.supported_levels))or(p.allow_development_mock is distinct from(cfg.provider_code='MATRICIA_DEV_MOCK'))then raise exception'SIGNATURE_PROVIDER_NOT_CONFIGURED'using errcode='55000';end if;
 return p;
end$$;
-- Withdrawal is a new immutable fact, so the original authority history remains intact.
create table public.signature_authority_revocations_v1(
 authority_id uuid primary key references public.signature_signer_authorities(id),revoked_by uuid not null references auth.users(id),
 reason text not null check(length(btrim(reason))between 20 and 1000),idempotency_key uuid not null unique,revoked_at timestamptz not null default clock_timestamp()
);
alter table public.signature_authority_revocations_v1 enable row level security;
revoke all on public.signature_authority_revocations_v1 from public,anon,authenticated,service_role;grant select on public.signature_authority_revocations_v1 to authenticated;
create policy signature_authority_revocation_party_read on public.signature_authority_revocations_v1 for select to authenticated using(private.signature_envelope_access((select signer.envelope_id from public.signature_signer_authorities authority join public.signature_signers signer on signer.id=authority.signer_id where authority.id=authority_id)));
create trigger signature_authority_revocation_immutable before update or delete on public.signature_authority_revocations_v1 for each row execute function private.prevent_contract_immutable_change();

create function private.assert_contract_signature_parties_v1(p_envelope_id uuid,p_at timestamptz)returns void language plpgsql stable security definer set search_path=pg_catalog,private as $$
declare e public.signature_envelopes%rowtype;c public.contracts%rowtype;v public.contract_versions%rowtype;price bigint;begin
 select*into e from public.signature_envelopes where id=p_envelope_id;select*into c from public.contracts where id=e.contract_id;select*into v from public.contract_versions where id=e.contract_version_id;
 price:=v.price_minor+coalesce((select price_delta_minor from public.contract_amendments where id=e.amendment_id),0);
 if e.id is null or price<0 or(select count(*)from public.contract_parties where contract_version_id=v.id)<>2 or not exists(select 1 from public.contract_parties where contract_version_id=v.id and party_role='CLIENT'and organization_id=c.client_organization_id)or not exists(select 1 from public.contract_parties where contract_version_id=v.id and party_role='PROVIDER'and organization_id=c.provider_organization_id)or(select count(*)from public.signature_signers where envelope_id=e.id)<>2 then raise exception'SIGNATURE_EXACT_PARTIES_REQUIRED'using errcode='23514';end if;
 if exists(select 1 from public.signature_signers s where s.envelope_id=e.id and(not exists(select 1 from public.contract_parties q where q.contract_version_id=v.id and q.organization_id=s.organization_id)or not exists(select 1 from auth.users u where u.id=s.signer_user_id and u.email_confirmed_at is not null and s.email_hash=encode(extensions.digest(lower(btrim(u.email)),'sha256'),'hex'))or not private.has_org_role(s.organization_id,array[s.signer_role],s.signer_user_id)or not private.has_org_role(s.organization_id,case when s.organization_id=c.client_organization_id then array['CLIENT_OWNER','CLIENT_ADMIN']else array['PROVIDER_OWNER','PROVIDER_MANAGER']end,s.signer_user_id)or not exists(select 1 from public.signature_signer_authorities a where a.signer_id=s.id and a.organization_id=s.organization_id and a.status='ACTIVE'and a.revoked_at is null and not exists(select 1 from public.signature_authority_revocations_v1 revoked where revoked.authority_id=a.id and revoked.revoked_at<=p_at)and(p_at at time zone'UTC')::date between a.valid_from and coalesce(a.valid_until,'infinity'::date)and'CONTRACT_SIGNATURE'=any(a.authority_scope)and(a.amount_ceiling_minor is null or(a.currency=v.currency and a.amount_ceiling_minor>=price)))))then raise exception'SIGNER_AUTHORITY_REQUIRED'using errcode='23514';end if;
end$$;
create function private.freeze_contract_signature_binding_v1()returns trigger language plpgsql security definer set search_path=pg_catalog,private as $$
declare e public.signature_envelopes%rowtype;v public.contract_versions%rowtype;am public.contract_amendments%rowtype;p private.contract_signature_policy_versions_v1%rowtype;a private.contract_signature_source_artifacts_v1%rowtype;kind text;source uuid;hash text;parties text;begin
 if new.status<>'READY_FOR_SIGNATURE'or old.status='READY_FOR_SIGNATURE'then return new;end if;
 select*into e from public.signature_envelopes where id=new.id;select*into v from public.contract_versions where id=e.contract_version_id;select*into am from public.contract_amendments where id=e.amendment_id;
 kind:=case when e.amendment_id is null then'CONTRACT'else'AMENDMENT'end;source:=coalesce(e.amendment_id,v.id);hash:=case when e.amendment_id is null then v.content_hash else am.content_hash end;
 p:=private.require_contract_signature_policy_v1(kind);
 if e.provider_config_id<>p.provider_config_id or array_position(array['SIMPLE','ADVANCED','QUALIFIED'],e.requested_level)<array_position(array['SIMPLE','ADVANCED','QUALIFIED'],p.minimum_level)or(e.amendment_id is not null and(am.contract_id<>e.contract_id or am.base_contract_version_id<>v.id or am.status not in('DRAFT','PENDING_SIGNATURE')))then raise exception'SIGNATURE_POLICY_SCOPE_MISMATCH'using errcode='23514';end if;
 perform private.assert_contract_signature_parties_v1(e.id,clock_timestamp());parties:=private.contract_signature_parties_hash_v1(v.id);
 if(select count(*)from public.signature_documents where envelope_id=e.id)<>1 or not exists(select 1 from public.signature_documents where envelope_id=e.id and document_type=kind and contract_version_id=v.id and exact_version=case when kind='CONTRACT'then v.version else am.amendment_number end and sha256=e.document_set_hash)then raise exception'SIGNATURE_EXACT_DOCUMENT_REQUIRED'using errcode='23514';end if;
 select*into a from private.contract_signature_source_artifacts_v1 where source_kind=kind and source_id=source and contract_version_id=v.id and source_hash=hash and parties_hash=parties and pdf_sha256=e.document_set_hash and storage_path=(select storage_path from public.signature_documents where envelope_id=e.id)and verified_at<=clock_timestamp()and exists(select 1 from storage.objects o join storage.buckets bucket on bucket.id=o.bucket_id where o.id=storage_object_id and o.name=storage_path and not bucket.public);
 if a.id is null and not p.allow_development_mock then raise exception'SIGNATURE_DOCUMENT_ARCHIVE_REQUIRED'using errcode='55000';end if;
 insert into private.contract_signature_bindings_v1(envelope_id,policy_version_id,contract_version_id,contract_version_hash,requested_level,source_kind,source_id,source_hash,parties_hash,signers_hash,documents_hash,pdf_sha256,source_artifact_id)values(e.id,p.id,v.id,v.content_hash,e.requested_level,kind,source,hash,parties,private.contract_signature_signers_hash_v1(e.id),private.contract_signature_documents_hash_v1(e.id),e.document_set_hash,a.id);
 return new;
end$$;
create trigger signature_contract_binding_freeze after update of status on public.signature_envelopes for each row when(new.status='READY_FOR_SIGNATURE'and old.status is distinct from'READY_FOR_SIGNATURE')execute function private.freeze_contract_signature_binding_v1();
create function private.assert_contract_signature_binding_v1(p_envelope_id uuid,p_completed boolean default false)returns private.contract_signature_bindings_v1 language plpgsql stable security definer set search_path=pg_catalog,private as $$
declare e public.signature_envelopes%rowtype;v public.contract_versions%rowtype;c public.contracts%rowtype;am public.contract_amendments%rowtype;b private.contract_signature_bindings_v1%rowtype;p private.contract_signature_policy_versions_v1%rowtype;cfg public.signature_provider_configs%rowtype;begin
 select*into e from public.signature_envelopes where id=p_envelope_id;select*into b from private.contract_signature_bindings_v1 where envelope_id=e.id;select*into p from private.contract_signature_policy_versions_v1 where id=b.policy_version_id;select*into cfg from public.signature_provider_configs where id=e.provider_config_id;
 perform private.require_signature_environment_v1(cfg.environment,e.provider_code);
 select*into v from public.contract_versions where id=e.contract_version_id;select*into c from public.contracts where id=e.contract_id;select*into am from public.contract_amendments where id=e.amendment_id;
 if b.envelope_id is null or p.provider_config_id is distinct from e.provider_config_id or p.environment is distinct from cfg.environment or p.approved_at>b.bound_at or b.bound_at>=p.valid_until or b.source_id is distinct from coalesce(e.amendment_id,v.id)or b.requested_level is distinct from e.requested_level or b.contract_version_id is distinct from v.id or b.contract_version_hash is distinct from v.content_hash or b.pdf_sha256 is distinct from e.document_set_hash or b.parties_hash is distinct from private.contract_signature_parties_hash_v1(v.id)or b.signers_hash is distinct from private.contract_signature_signers_hash_v1(e.id)or b.documents_hash is distinct from private.contract_signature_documents_hash_v1(e.id)or b.source_hash is distinct from(case when e.amendment_id is null then v.content_hash else am.content_hash end)or(b.source_kind='AMENDMENT')<>(e.amendment_id is not null)or(b.source_kind='AMENDMENT'and(am.contract_id is distinct from c.id or am.base_contract_version_id is distinct from v.id))or(not p_completed and b.source_kind='CONTRACT'and v.version<>c.current_version)or(not p_completed and b.source_kind='AMENDMENT'and v.version<>c.current_version and am.activated_contract_version_id is distinct from(select id from public.contract_versions where contract_id=c.id and version=c.current_version))then raise exception'SIGNATURE_SOURCE_BINDING_MISMATCH'using errcode='23514';end if;
 if cfg.provider_code='MATRICIA_DEV_MOCK'and not p.allow_development_mock then raise exception'SIGNATURE_DEVELOPMENT_PROVIDER_FORBIDDEN'using errcode='42501';end if;
 if not p_completed then
  if (private.require_contract_signature_policy_v1(b.source_kind)).id is distinct from p.id then raise exception'SIGNATURE_POLICY_SCOPE_MISMATCH'using errcode='23514';end if;
  perform private.assert_contract_signature_parties_v1(e.id,clock_timestamp());
 end if;
 if p_completed and(e.status<>'SIGNED'or e.completed_at is null or e.achieved_level is distinct from e.requested_level or array_position(array['SIMPLE','ADVANCED','QUALIFIED'],e.achieved_level)<array_position(array['SIMPLE','ADVANCED','QUALIFIED'],p.minimum_level)or exists(select 1 from public.signature_signers where envelope_id=e.id and(status<>'SIGNED'or achieved_level is distinct from e.achieved_level)))then raise exception'SIGNATURE_COMPLETED_ENVELOPE_REQUIRED'using errcode='23514';end if;
 return b;
end$$;
create function private.require_completed_contract_signature_v1(p_envelope_id uuid)returns public.signature_evidence_packages language plpgsql stable security definer set search_path=pg_catalog,private set timezone='UTC' as $$
declare e public.signature_envelopes%rowtype;b private.contract_signature_bindings_v1%rowtype;p private.contract_signature_policy_versions_v1%rowtype;ep public.signature_evidence_packages%rowtype;last_event public.signature_provider_events%rowtype;expected text;begin
 b:=private.assert_contract_signature_binding_v1(p_envelope_id,true);select*into e from public.signature_envelopes where id=p_envelope_id;select*into p from private.contract_signature_policy_versions_v1 where id=b.policy_version_id;select*into ep from public.signature_evidence_packages where envelope_id=e.id;
 if ep.id is null or ep.contract_version_id is distinct from e.contract_version_id or ep.pdf_sha256 is distinct from b.pdf_sha256 or ep.source_binding_hash is distinct from private.canonical_request_hash(to_jsonb(b)-'bound_at')or ep.verification_result not in('VERIFIED','VERIFIED_WITH_LIMITATIONS')or ep.provider_snapshot->>'provider_code'is distinct from e.provider_code or ep.provider_snapshot->>'achieved_level'is distinct from e.achieved_level or e.completed_at>p.valid_until then raise exception'SIGNATURE_COMPLETED_EVIDENCE_REQUIRED'using errcode='23514';end if;
 expected:=private.canonical_request_hash(jsonb_build_object('envelope_id',e.id,'contract_version_id',e.contract_version_id,'pdf_sha256',e.document_set_hash,'signers',ep.signer_actions_snapshot,'provider',e.provider_code,'level',e.achieved_level,'event_chain_hash',ep.event_chain_hash,'source_binding_hash',ep.source_binding_hash));
 if ep.final_hash<>expected then raise exception'SIGNATURE_EVIDENCE_HASH_MISMATCH'using errcode='23514';end if;
 select*into last_event from public.signature_provider_events where envelope_id=e.id and event_type='SIGNER_SIGNED'and signature_verified and processing_result->>'outcome'='SIGNATURE_ENVELOPE_SIGNED'order by id desc limit 1;
 expected:=private.canonical_request_hash(jsonb_build_object('previous_events',(select coalesce(jsonb_agg(jsonb_build_object('provider_event_id',q.provider_event_id,'payload_hash',q.payload_hash)order by q.id),'[]')from public.signature_provider_events q where q.envelope_id=e.id and q.id<last_event.id),'current_event_id',last_event.provider_event_id,'current_payload_hash',last_event.payload_hash));
 if last_event.id is null or ep.event_chain_hash<>expected or ep.signer_actions_snapshot is distinct from(select jsonb_agg(jsonb_build_object('signer_id',s.id,'organization_id',s.organization_id,'signer_user_id',s.signer_user_id,'role',s.signer_role,'signed_at',s.signed_at)order by s.signing_order)from public.signature_signers s where s.envelope_id=e.id)or exists(select 1 from public.signature_signers s where s.envelope_id=e.id and not exists(select 1 from public.signature_attempts a join public.signature_provider_events v on v.envelope_id=a.envelope_id and v.provider_event_id=a.provider_request_id and v.signature_verified and v.event_type='SIGNER_SIGNED'where a.envelope_id=e.id and a.signer_id=s.id and a.attempt_type='SIGN'and a.outcome='SUCCEEDED'))then raise exception'SIGNATURE_PROVIDER_CHAIN_REQUIRED'using errcode='23514';end if;
 if not p.allow_development_mock and ep.consent_snapshot='{}'::jsonb then raise exception'SIGNATURE_PROVIDER_CONSENT_REQUIRED'using errcode='23514';end if;
 if p.require_certificate and exists(select 1 from public.signature_signers s where s.envelope_id=e.id and not exists(select 1 from public.signature_certificates cert where cert.evidence_package_id=ep.id and cert.signer_id=s.id and cert.verification_status='VERIFIED'and cert.valid_from<=s.signed_at and cert.valid_until>=s.signed_at and(e.achieved_level<>'QUALIFIED'or cert.qualification_status='QUALIFIED')))then raise exception'SIGNATURE_EACH_PARTY_CERTIFICATE_REQUIRED'using errcode='23514';end if;
 if p.require_trusted_timestamp and exists(select 1 from public.signature_signers s where s.envelope_id=e.id and not exists(select 1 from public.trusted_timestamps t where t.evidence_package_id=ep.id and(t.signer_id=s.id or t.signer_id is null)and t.verification_status='VERIFIED'and abs(extract(epoch from(t.timestamped_at-s.signed_at)))<=300))then raise exception'SIGNATURE_EACH_PARTY_TIMESTAMP_REQUIRED'using errcode='23514';end if;
 return ep;
end$$;

create function private.apply_verified_contract_amendment_v1(p_verified_actor uuid,p_amendment_id uuid,p_organization_id uuid,p_expected_hash text,p_signer_role text,p_proof jsonb,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb
language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare actor uuid:=p_verified_actor;am public.contract_amendments%rowtype;c public.contracts%rowtype;base public.contract_versions%rowtype;cr public.change_requests%rowtype;sig uuid;signature_count integer;new_version integer;new_version_id uuid;new_hash text;r jsonb;request_data jsonb;delta jsonb;
begin select*into am from public.contract_amendments where id=p_amendment_id;select*into c from public.contracts where id=am.contract_id;
 if actor is null or am.id is null or p_organization_id not in(c.client_organization_id,c.provider_organization_id)or not private.has_org_role(p_organization_id,case when p_organization_id=c.client_organization_id then array['CLIENT_OWNER','CLIENT_ADMIN']else array['PROVIDER_OWNER','PROVIDER_MANAGER']end,actor)then raise exception'AMENDMENT_SIGN_AAL2_REQUIRED'using errcode='42501';end if;
 if am.status<>'PENDING_SIGNATURE'or p_expected_hash<>am.content_hash then raise exception'STALE_AMENDMENT'using errcode='40001';end if;if jsonb_typeof(p_proof)<>'object'or not(p_proof?&array['method','signed_at','evidence_hash'])or p_proof->>'evidence_hash'!~'^[0-9a-f]{64}$'or p_signer_role!~'^[A-Z][A-Z0-9_]{2,79}$'then raise exception'INVALID_AMENDMENT_SIGNATURE'using errcode='22023';end if;
 new_hash:=private.canonical_request_hash(jsonb_build_object('amendment',am.id,'organization',p_organization_id,'hash',p_expected_hash,'role',p_signer_role,'proof',p_proof));r:=private.begin_contract_command(c.client_organization_id,'contract.amendment.sign.'||am.id::text||'.'||p_organization_id::text,p_idempotency_key,new_hash,actor);if r is not null then return r;end if;
 perform pg_advisory_xact_lock(hashtextextended('contract-amendment:'||am.id::text,0));select*into am from public.contract_amendments where id=am.id for update;if am.status<>'PENDING_SIGNATURE'then raise exception'INVALID_AMENDMENT_SIGN_TRANSITION'using errcode='55000';end if;
 insert into public.contract_amendment_signatures(amendment_id,organization_id,signer_user_id,signer_role,amendment_hash,proof,correlation_id)values(am.id,p_organization_id,actor,p_signer_role,am.content_hash,p_proof,p_correlation_id)returning id into sig;select count(*)into signature_count from public.contract_amendment_signatures where amendment_id=am.id;
 if signature_count=2 then
  select*into c from public.contracts where id=am.contract_id for update;select*into base from public.contract_versions where id=am.base_contract_version_id;select*into cr from public.change_requests where id=am.change_request_id;if base.version<>c.current_version or base.price_minor+am.price_delta_minor<0 then raise exception'STALE_AMENDMENT_BASE_VERSION'using errcode='40001';end if;new_version:=c.current_version+1;request_data:=base.request_snapshot||jsonb_build_object('amendment_id',am.id,'scope_delta',cr.scope_delta,'deadline_delta_days',am.deadline_delta_days);new_hash:=private.canonical_request_hash(jsonb_build_object('contract',c.id,'version',new_version,'request',request_data,'quote',base.quote_snapshot,'clauses',base.clauses,'price_minor',base.price_minor+am.price_delta_minor,'currency',base.currency,'commission',am.commission_rule_snapshot,'amendment_hash',am.content_hash));
  insert into public.contract_versions(contract_id,version,request_snapshot,quote_snapshot,clauses,price_minor,currency,commission_rule_snapshot,content_hash,change_reason,created_by)values(c.id,new_version,request_data,base.quote_snapshot,base.clauses,base.price_minor+am.price_delta_minor,base.currency,am.commission_rule_snapshot,new_hash,'Activated amendment #'||am.amendment_number,actor)returning id into new_version_id;
  insert into public.contract_parties(contract_version_id,organization_id,party_role,legal_snapshot)select new_version_id,organization_id,party_role,legal_snapshot from public.contract_parties where contract_version_id=base.id;
  insert into public.contract_items(contract_version_id,item_key,item_type,label_fr,label_ar,details,sort_order)select new_version_id,i.item_key,i.item_type,i.label_fr,i.label_ar,i.details,i.sort_order from public.contract_items i where i.contract_version_id=base.id and not exists(select 1 from jsonb_array_elements(am.deliverables_delta)d where d->>'item_key'=i.item_key and d->>'operation'in('REMOVE','REPLACE'));
  for delta in select*from jsonb_array_elements(am.deliverables_delta)loop if delta->>'operation'in('ADD','REPLACE')then if delta->>'item_key'!~'^[A-Z][A-Z0-9_-]{1,79}$'or delta->>'item_type'not in('DELIVERABLE','EXCLUSION','ACCEPTANCE_CRITERION','PAYMENT_TERM','CORRECTION','PENALTY')or length(btrim(coalesce(delta->>'label_fr','')))=0 or length(btrim(coalesce(delta->>'label_ar','')))=0 then raise exception'INVALID_AMENDMENT_DELIVERABLE_DELTA'using errcode='22023';end if;insert into public.contract_items(contract_version_id,item_key,item_type,label_fr,label_ar,details,sort_order)values(new_version_id,delta->>'item_key',delta->>'item_type',delta->>'label_fr',delta->>'label_ar',coalesce(delta->'details','{}'),(delta->>'sort_order')::integer);end if;end loop;
  update public.contract_amendments set status='ACTIVE',activated_contract_version_id=new_version_id,activated_at=clock_timestamp()where id=am.id;update public.change_requests set status='ACCEPTED',decided_at=clock_timestamp()where id=am.change_request_id and status='REQUESTED';update public.contracts set current_version=new_version,status='AMENDED',row_version=row_version+1,updated_at=clock_timestamp()where id=c.id;update public.missions set contract_version_id=new_version_id,row_version=row_version+1,updated_at=clock_timestamp()where contract_id=c.id and status not in('COMPLETED','CANCELLED');
 end if;
 r:=jsonb_build_object('outcome',case when signature_count=2 then'CONTRACT_AMENDMENT_ACTIVATED'else'CONTRACT_AMENDMENT_PARTIALLY_SIGNED'end,'amendment_id',am.id,'contract_id',c.id,'signature_id',sig,'signature_count',signature_count,'contract_version_id',new_version_id,'version',new_version);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(c.client_organization_id,actor,'USER',case when signature_count=2 then'contract.amendment.activated'else'contract.amendment.signed'end,'contract_amendment',am.id::text,p_correlation_id,r,repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(c.client_organization_id,'contract_amendment',am.id::text,case when signature_count=2 then'ContractAmendmentActivatedV1'else'ContractAmendmentPartySignedV1'end,p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(c.client_organization_id,'contract.amendment.sign.'||am.id::text||'.'||p_organization_id::text,p_idempotency_key,r);return r;
end$$;

create function private.complete_contract_signatures_from_envelope_v1(p_envelope_id uuid,p_correlation_id uuid)returns void language plpgsql security definer set search_path=pg_catalog,private as $$
declare e public.signature_envelopes%rowtype;b private.contract_signature_bindings_v1%rowtype;ep public.signature_evidence_packages%rowtype;c public.contracts%rowtype;s public.signature_signers%rowtype;proof jsonb;result jsonb;begin
 ep:=private.require_completed_contract_signature_v1(p_envelope_id);select*into e from public.signature_envelopes where id=p_envelope_id;select*into b from private.contract_signature_bindings_v1 where envelope_id=e.id;select*into c from public.contracts where id=e.contract_id for update;
 if e.amendment_id is null and(not exists(select 1 from public.contract_versions where id=e.contract_version_id and contract_id=c.id and version=c.current_version)or c.status not in('PENDING_SIGNATURE','ACTIVE'))then raise exception'CONTRACT_SIGNATURE_SUBMISSION_REQUIRED'using errcode='55000';end if;
 for s in select*from public.signature_signers where envelope_id=e.id order by signing_order loop
  proof:=jsonb_build_object('method','SIGNATURE_PROVIDER_'||e.achieved_level,'signed_at',s.signed_at,'evidence_hash',ep.final_hash,'envelope_id',e.id,'evidence_package_id',ep.id,'policy_version_id',b.policy_version_id,'source_hash',b.source_hash,'pdf_sha256',b.pdf_sha256,'parties_hash',b.parties_hash,'source_binding_hash',ep.source_binding_hash,'development_mock',e.provider_code='MATRICIA_DEV_MOCK');
  if e.amendment_id is null then
   if exists(select 1 from public.contract_signatures q where q.contract_version_id=e.contract_version_id and q.organization_id=s.organization_id and(q.contract_hash is distinct from b.contract_version_hash or q.signer_user_id<>s.signer_user_id or q.proof->>'evidence_hash'is distinct from ep.final_hash))then raise exception'LEGACY_CONTRACT_SIGNATURE_REVIEW_REQUIRED'using errcode='55000';end if;
   insert into public.contract_signatures(contract_id,contract_version_id,organization_id,signer_user_id,signer_role,contract_hash,proof,signed_at,correlation_id)values(e.contract_id,e.contract_version_id,s.organization_id,s.signer_user_id,s.signer_role,b.contract_version_hash,proof,s.signed_at,p_correlation_id)on conflict(contract_version_id,organization_id)do nothing;
  else
   result:=private.apply_verified_contract_amendment_v1(s.signer_user_id,e.amendment_id,s.organization_id,b.source_hash,s.signer_role,proof,'signature-amendment:'||e.id::text||':'||s.organization_id::text,p_correlation_id);
  end if;
 end loop;
 if e.amendment_id is null then
  update public.contracts set status='ACTIVE',row_version=row_version+1,updated_at=clock_timestamp()where id=c.id and status='PENDING_SIGNATURE';
  if found then
   insert into public.audit_events(organization_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(c.client_organization_id,'SERVICE','contract.signed','contract',c.id::text,p_correlation_id,jsonb_build_object('envelope_id',e.id,'evidence_package_id',ep.id,'policy_version_id',b.policy_version_id,'development_mock',e.provider_code='MATRICIA_DEV_MOCK'),repeat('0',64));
   insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(c.client_organization_id,'contract',c.id::text,'ContractSignedV1',p_correlation_id,jsonb_build_object('contract_id',c.id,'contract_version_id',e.contract_version_id,'envelope_id',e.id,'evidence_package_id',ep.id),'signature-contract:'||e.id::text);
  end if;
 end if;
end$$;
create or replace function public.submit_contract_for_signature(p_contract_id uuid,p_expected_row_version integer,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,private,extensions as $$
declare actor uuid:=auth.uid();c public.contracts%rowtype;v public.contract_versions%rowtype;e public.signature_envelopes%rowtype;p private.contract_signature_policy_versions_v1%rowtype;hash text;r jsonb;begin
 select*into c from public.contracts where id=p_contract_id for update;
 if actor is null or c.id is null or auth.jwt()->>'aal'is distinct from'aal2'or not private.has_org_role(c.client_organization_id,array['CLIENT_OWNER','CLIENT_ADMIN'],actor)then raise exception'CONTRACT_SUBMIT_DENIED'using errcode='42501';end if;
 hash:=private.canonical_request_hash(jsonb_build_object('contract_id',p_contract_id,'expected',p_expected_row_version));r:=private.begin_contract_command(c.client_organization_id,'contract.submit',p_idempotency_key,hash,actor);if r is not null then return r;end if;
 if c.status<>'DRAFT'or c.row_version<>p_expected_row_version then raise exception'INVALID_CONTRACT_TRANSITION'using errcode='55000';end if;
 p:=private.require_contract_signature_policy_v1('CONTRACT');select*into v from public.contract_versions where contract_id=c.id and version=c.current_version;
 select*into e from public.signature_envelopes where contract_id=c.id and contract_version_id=v.id and amendment_id is null and provider_config_id=p.provider_config_id and status in('DRAFT','READY_FOR_SIGNATURE')order by envelope_version desc limit 1;
 if e.id is null then raise exception'SIGNATURE_ENVELOPE_REQUIRED'using errcode='55000';end if;
 if e.status='DRAFT'then perform public.ready_signature_envelope(e.id,e.row_version,'contract-ready:'||e.id::text,p_correlation_id);end if;
 perform private.assert_contract_signature_binding_v1(e.id,false);
 update public.contracts set status='PENDING_SIGNATURE',row_version=row_version+1,updated_at=clock_timestamp()where id=c.id;
 r:=jsonb_build_object('outcome','CONTRACT_PENDING_SIGNATURE','contract_id',c.id,'envelope_id',e.id,'row_version',c.row_version+1);
 insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(c.client_organization_id,actor,'USER','contract.submitted','contract',c.id::text,p_correlation_id,jsonb_build_object('envelope_id',e.id),repeat('0',64));
 insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(c.client_organization_id,'contract',c.id::text,'ContractSignatureRequestedV1',p_correlation_id,r,p_idempotency_key);
 perform private.finish_contract_command(c.client_organization_id,'contract.submit',p_idempotency_key,r);return r;
end$$;
create or replace function public.sign_contract(p_contract_id uuid,p_contract_version_id uuid,p_organization_id uuid,p_expected_contract_hash text,p_signer_role text,p_proof jsonb,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,private,extensions as $$
declare actor uuid:=auth.uid();c public.contracts%rowtype;v public.contract_versions%rowtype;e public.signature_envelopes%rowtype;ep public.signature_evidence_packages%rowtype;s public.contract_signatures%rowtype;begin
 select*into c from public.contracts where id=p_contract_id;
 if actor is null or c.id is null or auth.jwt()->>'aal'is distinct from'aal2'or p_organization_id not in(c.client_organization_id,c.provider_organization_id)or not private.has_org_role(p_organization_id,case when p_organization_id=c.client_organization_id then array['CLIENT_OWNER','CLIENT_ADMIN']else array['PROVIDER_OWNER','PROVIDER_MANAGER']end,actor)then raise exception'CONTRACT_SIGN_DENIED'using errcode='42501';end if;
 select*into v from public.contract_versions where id=p_contract_version_id and contract_id=c.id and version=c.current_version;
 if v.id is null or v.content_hash is distinct from p_expected_contract_hash then raise exception'STALE_CONTRACT_VERSION'using errcode='40001';end if;
 if jsonb_typeof(p_proof)is distinct from'object'or not(p_proof?&array['envelope_id','evidence_package_id','final_hash'])or p_proof-array['envelope_id','evidence_package_id','final_hash']<>'{}'::jsonb or coalesce(p_proof->>'envelope_id','')!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'or coalesce(p_proof->>'evidence_package_id','')!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'then raise exception'SIGNATURE_PROVIDER_EVIDENCE_REQUIRED'using errcode='55000';end if;
 select*into e from public.signature_envelopes where id=(p_proof->>'envelope_id')::uuid and contract_id=c.id and contract_version_id=v.id and amendment_id is null;
 if e.id is null then raise exception'SIGNATURE_SOURCE_BINDING_MISMATCH'using errcode='23514';end if;
 ep:=private.require_completed_contract_signature_v1(e.id);
 if ep.id is distinct from(p_proof->>'evidence_package_id')::uuid or ep.final_hash is distinct from p_proof->>'final_hash'then raise exception'SIGNATURE_EVIDENCE_HASH_MISMATCH'using errcode='23514';end if;
 select*into s from public.contract_signatures where contract_version_id=v.id and organization_id=p_organization_id and signer_user_id=actor and signer_role=p_signer_role and contract_hash=v.content_hash and proof->>'evidence_hash'=ep.final_hash;
 if s.id is null or c.status<>'ACTIVE'then raise exception'SIGNATURE_COMPLETED_EVIDENCE_REQUIRED'using errcode='23514';end if;
 -- Read the imported fact; client-supplied JSON never creates a signature or an ACTIVE transition.
 return jsonb_build_object('outcome','CONTRACT_SIGNED','contract_id',c.id,'contract_version_id',v.id,'signature_id',s.id,'signature_count',2,'envelope_id',e.id,'evidence_package_id',ep.id);
end$$;
create function public.create_amendment_signature_envelope(p_amendment_id uuid,p_provider_code text,p_environment text,p_requested_level text,p_document_file_name text,p_document_storage_path text,p_document_sha256 text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,private,extensions as $$
declare actor uuid:=auth.uid();am public.contract_amendments%rowtype;c public.contracts%rowtype;cfg public.signature_provider_configs%rowtype;prior public.signature_envelopes%rowtype;e uuid;envelope_number integer;hash text;begin
 select*into am from public.contract_amendments where id=p_amendment_id;select*into c from public.contracts where id=am.contract_id for update;
 if actor is null or am.id is null or not private.has_org_role(c.client_organization_id,array['CLIENT_OWNER','CLIENT_ADMIN'],actor)then raise exception'SIGNATURE_ENVELOPE_CREATE_DENIED'using errcode='42501';end if;
 perform private.require_signature_environment_v1(p_environment,p_provider_code);
 select*into cfg from public.signature_provider_configs where provider_code=p_provider_code and environment=p_environment and status='ACTIVE'and valid_from<=clock_timestamp()and(valid_until is null or valid_until>clock_timestamp())order by version desc limit 1;
 if cfg.id is null or p_requested_level is null or not(p_requested_level=any(cfg.supported_levels))then raise exception'SIGNATURE_LEVEL_NOT_SUPPORTED'using errcode='23514';end if;
 if am.status not in('DRAFT','PENDING_SIGNATURE')or not exists(select 1 from public.contract_versions where id=am.base_contract_version_id and contract_id=c.id and version=c.current_version)then raise exception'STALE_AMENDMENT_BASE_VERSION'using errcode='40001';end if;
 if p_document_sha256 is null or p_document_sha256!~'^[0-9a-f]{64}$'or length(btrim(coalesce(p_document_file_name,'')))not between 1 and 255 or length(btrim(coalesce(p_document_storage_path,'')))not between 3 and 1000 or length(coalesce(p_idempotency_key,''))not between 8 and 200 then raise exception'INVALID_SIGNATURE_ENVELOPE'using errcode='22023';end if;
 hash:=private.canonical_request_hash(jsonb_build_object('amendment_id',am.id,'amendment_hash',am.content_hash,'base_version',am.base_contract_version_id,'provider_config',cfg.id,'requested_level',p_requested_level,'document_sha256',p_document_sha256));
 select*into prior from public.signature_envelopes where client_organization_id=c.client_organization_id and idempotency_key=p_idempotency_key;
 if found then if prior.request_hash<>hash then raise exception'SIGNATURE_ENVELOPE_IDEMPOTENCY_MISMATCH'using errcode='22000';end if;return jsonb_build_object('outcome','SIGNATURE_ENVELOPE_CREATED','envelope_id',prior.id,'replayed',true);end if;
 if exists(select 1 from public.signature_envelopes where amendment_id=am.id and status in('DRAFT','READY_FOR_SIGNATURE','SENT','PARTIALLY_SIGNED','SIGNED'))then raise exception'SIGNATURE_ENVELOPE_ALREADY_ACTIVE'using errcode='55000';end if;
 select coalesce(max(envelope_version),0)+1 into envelope_number from public.signature_envelopes where contract_id=c.id;
 select*into prior from public.signature_envelopes where amendment_id=am.id order by envelope_version desc limit 1;
 insert into public.signature_envelopes(client_organization_id,contract_id,contract_version_id,amendment_id,provider_config_id,provider_code,envelope_version,supersedes_envelope_id,requested_level,document_set_hash,idempotency_key,request_hash,correlation_id,created_by)values(c.client_organization_id,c.id,am.base_contract_version_id,am.id,cfg.id,cfg.provider_code,envelope_number,prior.id,p_requested_level,p_document_sha256,p_idempotency_key,hash,p_correlation_id,actor)returning id into e;
 insert into public.signature_documents(envelope_id,contract_version_id,document_type,exact_version,file_name,storage_path,sha256,sort_order)values(e,am.base_contract_version_id,'AMENDMENT',am.amendment_number,p_document_file_name,p_document_storage_path,p_document_sha256,1);
 insert into public.signature_attempts(envelope_id,attempt_type,outcome,correlation_id)values(e,'CREATE','SUCCEEDED',p_correlation_id);
 insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(c.client_organization_id,actor,'USER','signature.amendment_envelope_created','signature_envelope',e::text,p_correlation_id,jsonb_build_object('amendment_id',am.id,'source_hash',am.content_hash),repeat('0',64));
 return jsonb_build_object('outcome','SIGNATURE_ENVELOPE_CREATED','envelope_id',e,'amendment_id',am.id,'envelope_version',envelope_number,'replayed',false);
end$$;
create or replace function public.submit_contract_amendment_for_signature(p_amendment_id uuid,p_expected_hash text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,private,extensions as $$
declare actor uuid:=auth.uid();am public.contract_amendments%rowtype;c public.contracts%rowtype;e public.signature_envelopes%rowtype;p private.contract_signature_policy_versions_v1%rowtype;hash text;r jsonb;begin
 select*into am from public.contract_amendments where id=p_amendment_id for update;select*into c from public.contracts where id=am.contract_id;
 if actor is null or am.id is null or auth.jwt()->>'aal'is distinct from'aal2'or not private.has_org_role(c.client_organization_id,array['CLIENT_OWNER','CLIENT_ADMIN'],actor)then raise exception'AMENDMENT_SUBMIT_AAL2_REQUIRED'using errcode='42501';end if;
 if p_expected_hash is distinct from am.content_hash then raise exception'STALE_AMENDMENT'using errcode='40001';end if;
 hash:=private.canonical_request_hash(jsonb_build_object('amendment',am.id,'hash',p_expected_hash));r:=private.begin_contract_command(c.client_organization_id,'contract.amendment.submit.'||am.id::text,p_idempotency_key,hash,actor);if r is not null then return r;end if;
 if am.status<>'DRAFT'then raise exception'INVALID_AMENDMENT_SUBMIT_TRANSITION'using errcode='55000';end if;
 p:=private.require_contract_signature_policy_v1('AMENDMENT');select*into e from public.signature_envelopes where amendment_id=am.id and contract_version_id=am.base_contract_version_id and provider_config_id=p.provider_config_id and status in('DRAFT','READY_FOR_SIGNATURE')order by envelope_version desc limit 1;
 if e.id is null then raise exception'SIGNATURE_ENVELOPE_REQUIRED'using errcode='55000';end if;
 if e.status='DRAFT'then perform public.ready_signature_envelope(e.id,e.row_version,'amendment-ready:'||e.id::text,p_correlation_id);end if;perform private.assert_contract_signature_binding_v1(e.id,false);
 update public.contract_amendments set status='PENDING_SIGNATURE'where id=am.id;
 r:=jsonb_build_object('outcome','CONTRACT_AMENDMENT_PENDING_SIGNATURE','amendment_id',am.id,'contract_id',c.id,'envelope_id',e.id);
 insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(c.client_organization_id,actor,'USER','contract.amendment.submitted','contract_amendment',am.id::text,p_correlation_id,jsonb_build_object('content_hash',am.content_hash,'envelope_id',e.id),repeat('0',64));
 insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(c.client_organization_id,'contract_amendment',am.id::text,'ContractAmendmentSignatureRequestedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(c.client_organization_id,'contract.amendment.submit.'||am.id::text,p_idempotency_key,r);return r;
end$$;
create or replace function public.sign_and_activate_contract_amendment(p_amendment_id uuid,p_organization_id uuid,p_expected_hash text,p_signer_role text,p_proof jsonb,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,private as $$
declare actor uuid:=auth.uid();am public.contract_amendments%rowtype;c public.contracts%rowtype;e public.signature_envelopes%rowtype;ep public.signature_evidence_packages%rowtype;s public.contract_amendment_signatures%rowtype;begin
 select*into am from public.contract_amendments where id=p_amendment_id;select*into c from public.contracts where id=am.contract_id;
 if actor is null or am.id is null or auth.jwt()->>'aal'is distinct from'aal2'or p_organization_id not in(c.client_organization_id,c.provider_organization_id)or not private.has_org_role(p_organization_id,case when p_organization_id=c.client_organization_id then array['CLIENT_OWNER','CLIENT_ADMIN']else array['PROVIDER_OWNER','PROVIDER_MANAGER']end,actor)then raise exception'AMENDMENT_SIGN_AAL2_REQUIRED'using errcode='42501';end if;
 if p_expected_hash is distinct from am.content_hash then raise exception'STALE_AMENDMENT'using errcode='40001';end if;
 if jsonb_typeof(p_proof)is distinct from'object'or not(p_proof?&array['envelope_id','evidence_package_id','final_hash'])or p_proof-array['envelope_id','evidence_package_id','final_hash']<>'{}'::jsonb or coalesce(p_proof->>'envelope_id','')!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'or coalesce(p_proof->>'evidence_package_id','')!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'then raise exception'SIGNATURE_PROVIDER_EVIDENCE_REQUIRED'using errcode='55000';end if;
 select*into e from public.signature_envelopes where id=(p_proof->>'envelope_id')::uuid and amendment_id=am.id and contract_id=c.id and contract_version_id=am.base_contract_version_id;
 if e.id is null then raise exception'SIGNATURE_SOURCE_BINDING_MISMATCH'using errcode='23514';end if;ep:=private.require_completed_contract_signature_v1(e.id);
 if ep.id is distinct from(p_proof->>'evidence_package_id')::uuid or ep.final_hash is distinct from p_proof->>'final_hash'then raise exception'SIGNATURE_EVIDENCE_HASH_MISMATCH'using errcode='23514';end if;
 select*into s from public.contract_amendment_signatures where amendment_id=am.id and organization_id=p_organization_id and signer_user_id=actor and signer_role=p_signer_role and amendment_hash=am.content_hash and proof->>'evidence_hash'=ep.final_hash;
 if s.id is null or am.status<>'ACTIVE'then raise exception'SIGNATURE_COMPLETED_EVIDENCE_REQUIRED'using errcode='23514';end if;
 return jsonb_build_object('outcome','CONTRACT_AMENDMENT_ACTIVATED','amendment_id',am.id,'contract_id',c.id,'signature_id',s.id,'signature_count',2,'activated_contract_version_id',am.activated_contract_version_id);
end$$;

create or replace function public.process_verified_signature_provider_event(p_envelope_id uuid,p_provider_code text,p_provider_event_id text,p_nonce text,p_event_type text,p_signer_id uuid,p_provider_occurred_at timestamptz,p_payload_hash text,p_signature_fingerprint text,p_signature_verified boolean,p_achieved_level text,p_provider_evidence jsonb,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb
language plpgsql security definer set search_path=pg_catalog,public,private,auth,extensions set timezone='UTC' as $$
declare e public.signature_envelopes%rowtype;cfg public.signature_provider_configs%rowtype;old public.signature_provider_events%rowtype;s public.signature_signers%rowtype;cnt integer;total integer;r jsonb;ep uuid;actions jsonb;final_hash text;event_chain text;
begin
 if coalesce(auth.role(),'')<>'service_role'then raise exception'SIGNATURE_EVENT_PROCESS_DENIED'using errcode='42501';end if;
 select * into e from public.signature_envelopes where id=p_envelope_id;select * into cfg from public.signature_provider_configs where id=e.provider_config_id;
 if e.id is null or cfg.provider_code<>p_provider_code or p_event_type not in('SENT','SIGNER_SIGNED','DECLINED','EXPIRED','FAILED','VOIDED')or p_payload_hash!~'^[0-9a-f]{64}$'or p_signature_fingerprint!~'^[0-9a-f]{64}$'or p_signature_verified is not true or abs(extract(epoch from(clock_timestamp()-p_provider_occurred_at)))>cfg.webhook_tolerance_seconds then raise exception'INVALID_VERIFIED_SIGNATURE_EVENT'using errcode='22023';end if;
 perform private.require_signature_environment_v1(cfg.environment,cfg.provider_code);
 perform pg_advisory_xact_lock(hashtextextended(p_provider_code||':'||p_provider_event_id,0));
 select * into old from public.signature_provider_events where provider_code=p_provider_code and provider_event_id=p_provider_event_id;
 if found then if old.envelope_id<>e.id or old.nonce<>p_nonce or old.event_type<>p_event_type or old.payload_hash<>p_payload_hash or old.signature_fingerprint<>p_signature_fingerprint then raise exception'SIGNATURE_EVENT_REPLAY_MISMATCH'using errcode='22000';end if;return old.processing_result||jsonb_build_object('replayed',true);end if;
 if exists(select 1 from public.signature_provider_events where provider_code=p_provider_code and nonce=p_nonce)then raise exception'SIGNATURE_EVENT_REPLAY_MISMATCH'using errcode='22000';end if;
 select * into e from public.signature_envelopes where id=p_envelope_id for update;
 if(p_event_type='SENT'and e.status<>'READY_FOR_SIGNATURE')or(p_event_type='SIGNER_SIGNED'and e.status not in('SENT','PARTIALLY_SIGNED'))then raise exception'INVALID_SIGNATURE_EVENT_TRANSITION'using errcode='55000';end if;
 if p_event_type in('SENT','SIGNER_SIGNED')then perform private.assert_contract_signature_binding_v1(e.id,false);if(e.amendment_id is null and not exists(select 1 from public.contracts where id=e.contract_id and status='PENDING_SIGNATURE'))or(e.amendment_id is not null and not exists(select 1 from public.contract_amendments where id=e.amendment_id and status='PENDING_SIGNATURE'))then raise exception'CONTRACT_SIGNATURE_SUBMISSION_REQUIRED'using errcode='55000';end if;end if;
 if p_event_type='SENT'then if e.status<>'READY_FOR_SIGNATURE'then raise exception'INVALID_SIGNATURE_EVENT_TRANSITION'using errcode='55000';end if;update public.signature_envelopes set status='SENT',provider_envelope_id=coalesce(nullif(p_provider_evidence->>'provider_envelope_id',''),provider_envelope_id),sent_at=p_provider_occurred_at,row_version=row_version+1 where id=e.id;r:=jsonb_build_object('outcome','SIGNATURE_ENVELOPE_SENT','envelope_id',e.id,'replayed',false);
 elsif p_event_type='SIGNER_SIGNED'then
  if e.status not in('SENT','PARTIALLY_SIGNED')or p_signer_id is null then raise exception'INVALID_SIGNATURE_EVENT_TRANSITION'using errcode='55000';end if;
  if p_achieved_level is null or not(p_achieved_level=any(cfg.supported_levels))then raise exception'SIGNATURE_LEVEL_NOT_SUPPORTED'using errcode='23514';end if;
  select * into s from public.signature_signers where id=p_signer_id and envelope_id=e.id for update;if not found then raise exception'SIGNATURE_SIGNER_NOT_FOUND'using errcode='P0002';end if;
  if s.status<>'SIGNED'then update public.signature_signers set status='SIGNED',identity_verification_level=case p_achieved_level when'QUALIFIED'then'QUALIFIED'when'ADVANCED'then'STRONG'else'BASIC'end,signed_at=p_provider_occurred_at where id=s.id;end if;
  select count(*) into cnt from public.signature_signers where envelope_id=e.id and status='SIGNED';select count(*) into total from public.signature_signers where envelope_id=e.id;
  if cnt=total then
   if p_achieved_level<>e.requested_level then raise exception'QUALIFIED_LEVEL_NOT_ACHIEVED'using errcode='23514';end if;
   update public.signature_envelopes set status='SIGNED',achieved_level=p_achieved_level,completed_at=p_provider_occurred_at,row_version=row_version+1 where id=e.id;
   select jsonb_agg(jsonb_build_object('signer_id',x.id,'organization_id',x.organization_id,'signer_user_id',x.signer_user_id,'role',x.signer_role,'signed_at',x.signed_at)order by x.signing_order)into actions from public.signature_signers x where x.envelope_id=e.id;
   event_chain:=private.canonical_request_hash(jsonb_build_object('previous_events',(select coalesce(jsonb_agg(jsonb_build_object('provider_event_id',q.provider_event_id,'payload_hash',q.payload_hash)order by q.id),'[]')from public.signature_provider_events q where q.envelope_id=e.id),'current_event_id',p_provider_event_id,'current_payload_hash',p_payload_hash));
   final_hash:=private.canonical_request_hash(jsonb_build_object('envelope_id',e.id,'contract_version_id',e.contract_version_id,'pdf_sha256',e.document_set_hash,'signers',actions,'provider',p_provider_code,'level',p_achieved_level,'event_chain_hash',event_chain,'source_binding_hash',(select private.canonical_request_hash(to_jsonb(binding)-'bound_at')from private.contract_signature_bindings_v1 binding where envelope_id=e.id)));
   insert into public.signature_evidence_packages(source_binding_hash,envelope_id,contract_version_id,pdf_sha256,signer_actions_snapshot,consent_snapshot,provider_snapshot,event_chain_hash,verification_result,final_hash,correlation_id)values((select private.canonical_request_hash(to_jsonb(binding)-'bound_at')from private.contract_signature_bindings_v1 binding where envelope_id=e.id),e.id,e.contract_version_id,e.document_set_hash,actions,coalesce(p_provider_evidence->'consent','{}'),jsonb_build_object('provider_code',p_provider_code,'provider_config_version',cfg.version,'achieved_level',p_achieved_level,'provider_envelope_id',e.provider_envelope_id),event_chain,case when p_achieved_level='SIMPLE'then'VERIFIED_WITH_LIMITATIONS'else'VERIFIED'end,final_hash,p_correlation_id)returning id into ep;
   if p_provider_evidence?'certificate_fingerprint'then insert into public.signature_certificates(evidence_package_id,signer_id,provider_certificate_id,certificate_fingerprint,subject_hash,issuer_name,valid_from,valid_until,qualification_status,verification_status)values(ep,s.id,nullif(p_provider_evidence->>'certificate_id',''),p_provider_evidence->>'certificate_fingerprint',p_provider_evidence->>'certificate_subject_hash',nullif(p_provider_evidence->>'certificate_issuer',''),nullif(p_provider_evidence->>'certificate_valid_from','')::timestamptz,nullif(p_provider_evidence->>'certificate_valid_until','')::timestamptz,case when p_achieved_level='QUALIFIED'then'QUALIFIED'else'NOT_QUALIFIED'end,'VERIFIED');end if;
   if p_provider_evidence?'timestamp_token_hash'then insert into public.trusted_timestamps(evidence_package_id,signer_id,authority_name,token_hash,timestamped_at,verification_status)values(ep,s.id,coalesce(nullif(p_provider_evidence->>'timestamp_authority',''),'PROVIDER_TIMESTAMP'),p_provider_evidence->>'timestamp_token_hash',p_provider_occurred_at,'VERIFIED');end if;
   r:=jsonb_build_object('outcome','SIGNATURE_ENVELOPE_SIGNED','envelope_id',e.id,'evidence_package_id',ep,'final_hash',final_hash,'achieved_level',p_achieved_level,'replayed',false);
  else update public.signature_envelopes set status='PARTIALLY_SIGNED',row_version=row_version+1 where id=e.id;r:=jsonb_build_object('outcome','SIGNATURE_ENVELOPE_PARTIALLY_SIGNED','envelope_id',e.id,'signer_id',s.id,'signature_count',cnt,'replayed',false);end if;
 else
  if e.status not in('READY_FOR_SIGNATURE','SENT','PARTIALLY_SIGNED')then raise exception'INVALID_SIGNATURE_EVENT_TRANSITION'using errcode='55000';end if;
  update public.signature_envelopes set status=p_event_type,completed_at=p_provider_occurred_at,row_version=row_version+1 where id=e.id;
  r:=jsonb_build_object('outcome','SIGNATURE_ENVELOPE_'||p_event_type,'envelope_id',e.id,'replayed',false);
 end if;
 insert into public.signature_provider_events(envelope_id,provider_code,provider_event_id,nonce,event_type,provider_occurred_at,payload_hash,signature_fingerprint,signature_verified,processing_result,correlation_id)values(e.id,p_provider_code,p_provider_event_id,p_nonce,p_event_type,p_provider_occurred_at,p_payload_hash,p_signature_fingerprint,true,r,p_correlation_id);
 insert into public.signature_attempts(envelope_id,signer_id,attempt_type,outcome,provider_request_id,occurred_at,correlation_id,metadata)values(e.id,p_signer_id,case p_event_type when'SENT'then'SEND'when'SIGNER_SIGNED'then'SIGN'when'DECLINED'then'DECLINE'when'VOIDED'then'VOID'else'PROVIDER_CALLBACK'end,'SUCCEEDED',p_provider_event_id,p_provider_occurred_at,p_correlation_id,jsonb_build_object('event_type',p_event_type,'payload_hash',p_payload_hash));
 if r->>'outcome'='SIGNATURE_ENVELOPE_SIGNED'then perform private.complete_contract_signatures_from_envelope_v1(e.id,p_correlation_id);end if;
 insert into public.audit_events(organization_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(e.client_organization_id,'SERVICE','signature.provider_event_processed','signature_envelope',e.id::text,p_correlation_id,r||jsonb_build_object('provider_event_id',p_provider_event_id,'event_type',p_event_type),repeat('0',64));
 insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(e.client_organization_id,'signature_envelope',e.id::text,case when r->>'outcome'='SIGNATURE_ENVELOPE_SIGNED'then'SignatureEnvelopeSignedV1'else'SignatureEnvelopeTransitionedV1'end,p_correlation_id,r,p_provider_code||':'||p_provider_event_id);return r;
end$$;


create function private.contract_signature_readiness_v1(p_contract_id uuid,p_amendment_id uuid default null)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,private as $$
declare c public.contracts%rowtype;v public.contract_versions%rowtype;am public.contract_amendments%rowtype;e public.signature_envelopes%rowtype;p private.contract_signature_policy_versions_v1%rowtype;env text;kind text;source uuid;hash text;result jsonb;begin
 select*into c from public.contracts where id=p_contract_id;
 if auth.uid()is null or c.id is null or not private.contract_party_access(c.id,auth.uid())then raise exception'SIGNATURE_READINESS_DENIED'using errcode='42501';end if;
 if p_amendment_id is not null then select*into am from public.contract_amendments where id=p_amendment_id and contract_id=c.id;if am.id is null then raise exception'SIGNATURE_READINESS_DENIED'using errcode='42501';end if;end if;
 select environment into env from private.admin_execution_environment_v1 where singleton;kind:=case when am.id is null then'CONTRACT'else'AMENDMENT'end;
 select*into v from public.contract_versions where contract_id=c.id and(case when am.id is null then version=c.current_version else id=am.base_contract_version_id end);
 source:=coalesce(am.id,v.id);hash:=case when am.id is null then v.content_hash else am.content_hash end;
 result:=jsonb_build_object('contract_id',c.id,'amendment_id',am.id,'environment',env,'ready',false);
 if v.id is null then return result||jsonb_build_object('status','BLOCKED','reason','CONTRACT_VERSION_REQUIRED');end if;
 select*into e from public.signature_envelopes q where q.contract_id=c.id and q.status='SIGNED'and(case when am.id is null then(q.amendment_id is null and q.contract_version_id=v.id)or exists(select 1 from public.contract_amendments prior where prior.id=q.amendment_id and prior.activated_contract_version_id=v.id)else q.amendment_id=am.id end)order by envelope_version desc limit 1;
 if e.id is not null then
  begin perform private.require_completed_contract_signature_v1(e.id);return result||jsonb_build_object('status','SIGNED','reason','SIGNATURE_EVIDENCE_VERIFIED','envelope_id',e.id,'requested_level',e.requested_level);
  exception when others then return result||jsonb_build_object('status','BLOCKED','reason','SIGNATURE_LEGACY_PROOF_UNVERIFIED');end;
 end if;
 if(am.id is null and c.status in('ACTIVE','AMENDED','COMPLETED'))or(am.id is not null and am.status='ACTIVE')then return result||jsonb_build_object('status','BLOCKED','reason','SIGNATURE_LEGACY_PROOF_UNVERIFIED');end if;
 begin p:=private.require_contract_signature_policy_v1(kind);exception when sqlstate'55000'or sqlstate'42501'then return result||jsonb_build_object('status','NOT_CONFIGURED','reason','SIGNATURE_PROVIDER_NOT_CONFIGURED');end;
 if not p.allow_development_mock and not exists(select 1 from private.contract_signature_source_artifacts_v1 where source_kind=kind and source_id=source and contract_version_id=v.id and source_hash=hash and parties_hash=private.contract_signature_parties_hash_v1(v.id))then return result||jsonb_build_object('status','DOCUMENT_ARCHIVE_REQUIRED','reason','SIGNATURE_DOCUMENT_ARCHIVE_REQUIRED','requested_level',p.minimum_level);end if;
 select*into e from public.signature_envelopes where contract_id=c.id and contract_version_id=v.id and amendment_id is not distinct from am.id and status in('DRAFT','READY_FOR_SIGNATURE','SENT','PARTIALLY_SIGNED')order by envelope_version desc limit 1;
 if e.id is null then return result||jsonb_build_object('status','ENVELOPE_REQUIRED','reason','SIGNATURE_ENVELOPE_REQUIRED','requested_level',p.minimum_level);end if;
 result:=result||jsonb_build_object('envelope_id',e.id,'requested_level',e.requested_level);
 if e.provider_config_id<>p.provider_config_id or array_position(array['SIMPLE','ADVANCED','QUALIFIED'],e.requested_level)<array_position(array['SIMPLE','ADVANCED','QUALIFIED'],p.minimum_level)then return result||jsonb_build_object('status','BLOCKED','reason','SIGNATURE_POLICY_SCOPE_MISMATCH');end if;
 begin perform private.assert_contract_signature_parties_v1(e.id,statement_timestamp());if e.status<>'DRAFT'then perform private.assert_contract_signature_binding_v1(e.id,false);end if;exception when others then return result||jsonb_build_object('status','AUTHORITIES_REQUIRED','reason','SIGNER_AUTHORITY_REQUIRED');end;
 if e.status in('SENT','PARTIALLY_SIGNED')or(am.id is null and c.status='PENDING_SIGNATURE')or(am.id is not null and am.status='PENDING_SIGNATURE')then return result||jsonb_build_object('status','AWAITING_PROVIDER','reason','SIGNATURE_PROVIDER_PENDING');end if;
 if auth.jwt()->>'aal'is distinct from'aal2'or not private.has_org_role(c.client_organization_id,array['CLIENT_OWNER','CLIENT_ADMIN'],auth.uid())then return result||jsonb_build_object('status','BLOCKED','reason','SIGNATURE_CLIENT_AAL2_SUBMISSION_REQUIRED');end if;
 return result||jsonb_build_object('status','READY_TO_SUBMIT','ready',true,'reason','SIGNATURE_PREREQUISITES_VERIFIED');
end$$;
create function public.get_contract_signature_readiness_v1(p_contract_id uuid)returns jsonb language sql stable security definer set search_path=pg_catalog,private as $$select private.contract_signature_readiness_v1(p_contract_id,null)$$;
create function public.get_amendment_signature_readiness_v1(p_amendment_id uuid)returns jsonb language sql stable security definer set search_path=pg_catalog,private as $$select private.contract_signature_readiness_v1((select contract_id from public.contract_amendments where id=p_amendment_id),p_amendment_id)$$;
create function public.list_contract_signature_readiness_v1(p_contract_ids uuid[])returns jsonb language plpgsql stable security definer set search_path=pg_catalog,private as $$declare result jsonb:='[]';id uuid;begin
 if p_contract_ids is null or cardinality(p_contract_ids)>100 or cardinality(p_contract_ids)<1 then raise exception'SIGNATURE_READINESS_BATCH_LIMIT'using errcode='22023';end if;
 foreach id in array p_contract_ids loop result:=result||jsonb_build_array(public.get_contract_signature_readiness_v1(id));end loop;return result;
end$$;
create function public.list_amendment_signature_readiness_v1(p_amendment_ids uuid[])returns jsonb language plpgsql stable security definer set search_path=pg_catalog,private as $$declare result jsonb:='[]';id uuid;begin
 if p_amendment_ids is null or cardinality(p_amendment_ids)>100 or cardinality(p_amendment_ids)<1 then raise exception'SIGNATURE_READINESS_BATCH_LIMIT'using errcode='22023';end if;
 foreach id in array p_amendment_ids loop result:=result||jsonb_build_array(public.get_amendment_signature_readiness_v1(id));end loop;return result;
end$$;
-- Private authoritative proof routines cannot be invoked with a caller-supplied actor or raw proof.
revoke all on function private.contract_signature_parties_hash_v1(uuid),private.contract_signature_signers_hash_v1(uuid),private.contract_signature_documents_hash_v1(uuid),private.require_contract_signature_policy_v1(text),private.assert_contract_signature_parties_v1(uuid,timestamptz),private.freeze_contract_signature_binding_v1(),private.assert_contract_signature_binding_v1(uuid,boolean),private.require_completed_contract_signature_v1(uuid),private.complete_contract_signatures_from_envelope_v1(uuid,uuid),private.contract_signature_readiness_v1(uuid,uuid),private.apply_verified_contract_amendment_v1(uuid,uuid,uuid,text,text,jsonb,text,uuid)from public,anon,authenticated,service_role;
revoke all on function public.create_amendment_signature_envelope(uuid,text,text,text,text,text,text,text,uuid),public.get_contract_signature_readiness_v1(uuid),public.get_amendment_signature_readiness_v1(uuid),public.list_contract_signature_readiness_v1(uuid[]),public.list_amendment_signature_readiness_v1(uuid[])from public,anon,authenticated,service_role;
grant execute on function public.create_amendment_signature_envelope(uuid,text,text,text,text,text,text,text,uuid),public.get_contract_signature_readiness_v1(uuid),public.get_amendment_signature_readiness_v1(uuid),public.list_contract_signature_readiness_v1(uuid[]),public.list_amendment_signature_readiness_v1(uuid[])to authenticated;
revoke all on public.contract_signatures from public,anon,authenticated,service_role;grant select on public.contract_signatures to authenticated;
notify pgrst,'reload schema';

create or replace function public.add_signature_signer(p_envelope_id uuid,p_organization_id uuid,p_signer_user_id uuid,p_signer_role text,p_email_hash text,p_signing_order integer,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb
language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();e public.signature_envelopes%rowtype;c public.contracts%rowtype;s public.signature_signers%rowtype;r jsonb;
begin select * into e from public.signature_envelopes where id=p_envelope_id;select * into c from public.contracts where id=e.contract_id;
 if a is null or e.id is null or not private.has_org_role(c.client_organization_id,array['CLIENT_OWNER','CLIENT_ADMIN'],a)then raise exception'SIGNATURE_SIGNER_ADD_DENIED'using errcode='42501';end if;
 select * into s from public.signature_signers where envelope_id=e.id and idempotency_key=p_idempotency_key;if found then if s.organization_id<>p_organization_id or s.signer_user_id<>p_signer_user_id or s.signing_order<>p_signing_order or s.signer_role is distinct from p_signer_role or s.email_hash is distinct from p_email_hash then raise exception'SIGNATURE_SIGNER_IDEMPOTENCY_MISMATCH'using errcode='22000';end if;return jsonb_build_object('outcome','SIGNATURE_SIGNER_ADDED','signer_id',s.id,'replayed',true);end if;
 if e.status<>'DRAFT'or p_email_hash!~'^[0-9a-f]{64}$'or p_signer_role!~'^[A-Z][A-Z0-9_]{2,79}$'or p_signing_order<1 or p_organization_id not in(c.client_organization_id,c.provider_organization_id)or not private.is_active_org_member(p_organization_id,p_signer_user_id)then raise exception'INVALID_SIGNATURE_SIGNER'using errcode='22023';end if;
 insert into public.signature_signers(envelope_id,organization_id,signer_user_id,signer_role,email_hash,signing_order,idempotency_key)values(e.id,p_organization_id,p_signer_user_id,p_signer_role,p_email_hash,p_signing_order,p_idempotency_key)returning * into s;
 r:=jsonb_build_object('outcome','SIGNATURE_SIGNER_ADDED','envelope_id',e.id,'signer_id',s.id,'organization_id',p_organization_id,'replayed',false);
 insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(e.client_organization_id,a,'USER','signature.signer_added','signature_signer',s.id::text,p_correlation_id,r,repeat('0',64));
 insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(e.client_organization_id,'signature_envelope',e.id::text,'SignatureSignerAddedV1',p_correlation_id,r,p_idempotency_key);return r;end$$;

create or replace function public.authorize_signature_signer(p_signer_id uuid,p_authority_type text,p_authority_scope text[],p_amount_ceiling_minor bigint,p_currency char(3),p_valid_from date,p_valid_until date,p_evidence_storage_path text,p_evidence_sha256 text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb
language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();s public.signature_signers%rowtype;e public.signature_envelopes%rowtype;x public.signature_signer_authorities%rowtype;r jsonb;
begin select * into s from public.signature_signers where id=p_signer_id;select * into e from public.signature_envelopes where id=s.envelope_id;
 if a is null or s.id is null or auth.jwt()->>'aal'is distinct from'aal2'or not private.has_org_role(s.organization_id,array['CLIENT_OWNER','CLIENT_ADMIN','PROVIDER_OWNER','PROVIDER_MANAGER'],a)then raise exception'SIGNATURE_AUTHORITY_VERIFY_DENIED'using errcode='42501';end if;
 select * into x from public.signature_signer_authorities where signer_id=s.id and idempotency_key=p_idempotency_key;if found then if (x.authority_type,x.authority_scope,x.amount_ceiling_minor,x.currency,x.valid_from,x.valid_until,x.evidence_storage_path,x.evidence_sha256)is distinct from(p_authority_type,p_authority_scope,p_amount_ceiling_minor,p_currency,p_valid_from,p_valid_until,p_evidence_storage_path,p_evidence_sha256)then raise exception'SIGNATURE_AUTHORITY_IDEMPOTENCY_MISMATCH'using errcode='22000';end if;return jsonb_build_object('outcome','SIGNATURE_AUTHORITY_RECORDED','authority_id',x.id,'replayed',true);end if;
 if e.status<>'DRAFT'or p_authority_type not in('LEGAL_REPRESENTATIVE','MANDATE','DELEGATION')or not('CONTRACT_SIGNATURE'=any(p_authority_scope))or p_evidence_sha256!~'^[0-9a-f]{64}$'or length(btrim(coalesce(p_evidence_storage_path,'')))not between 3 and 1000 or p_valid_from is null or p_valid_until<p_valid_from or ((p_amount_ceiling_minor is null)<>(p_currency is null))then raise exception'INVALID_SIGNATURE_AUTHORITY'using errcode='22023';end if;
 insert into public.signature_signer_authorities(signer_id,organization_id,authority_type,authority_scope,amount_ceiling_minor,currency,valid_from,valid_until,evidence_storage_path,evidence_sha256,verified_by,idempotency_key)values(s.id,s.organization_id,p_authority_type,p_authority_scope,p_amount_ceiling_minor,p_currency,p_valid_from,p_valid_until,p_evidence_storage_path,p_evidence_sha256,a,p_idempotency_key)returning * into x;
 r:=jsonb_build_object('outcome','SIGNATURE_AUTHORITY_RECORDED','envelope_id',e.id,'signer_id',s.id,'authority_id',x.id,'replayed',false);
