create function public.revoke_signature_signer_authority_v1(p_authority_id uuid,p_reason text,p_idempotency_key uuid)returns jsonb language plpgsql security definer set search_path=pg_catalog,private as $$
declare actor uuid:=auth.uid();a public.signature_signer_authorities%rowtype;r public.signature_authority_revocations_v1%rowtype;e public.signature_envelopes%rowtype;begin
 select*into a from public.signature_signer_authorities where id=p_authority_id;
 if actor is null or a.id is null or auth.jwt()->>'aal'is distinct from'aal2'or not private.has_org_role(a.organization_id,array['CLIENT_OWNER','CLIENT_ADMIN','PROVIDER_OWNER','PROVIDER_MANAGER'],actor)then raise exception'SIGNATURE_AUTHORITY_REVOKE_DENIED'using errcode='42501';end if;
 if length(btrim(coalesce(p_reason,'')))not between 20 and 1000 or p_idempotency_key is null then raise exception'INVALID_SIGNATURE_AUTHORITY_REVOCATION'using errcode='22023';end if;
 if exists(select 1 from public.signature_authority_revocations_v1 where idempotency_key=p_idempotency_key and authority_id<>a.id)then raise exception'SIGNATURE_AUTHORITY_REVOCATION_REPLAY_MISMATCH'using errcode='22000';end if;
 select*into r from public.signature_authority_revocations_v1 where authority_id=a.id;
 if found then if r.authority_id<>a.id or r.reason<>btrim(p_reason)or r.revoked_by<>actor then raise exception'SIGNATURE_AUTHORITY_REVOCATION_REPLAY_MISMATCH'using errcode='22000';end if;return jsonb_build_object('outcome','SIGNATURE_AUTHORITY_REVOKED','authority_id',a.id,'revoked_at',r.revoked_at);end if;
 insert into public.signature_authority_revocations_v1(authority_id,revoked_by,reason,idempotency_key)values(a.id,actor,btrim(p_reason),p_idempotency_key)returning*into r;
 select*into e from public.signature_envelopes where id=(select envelope_id from public.signature_signers where id=a.signer_id);
 insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(a.organization_id,actor,'USER','signature.authority_revoked','signature_signer_authority',a.id::text,p_idempotency_key,jsonb_build_object('envelope_id',e.id),repeat('0',64));
 return jsonb_build_object('outcome','SIGNATURE_AUTHORITY_REVOKED','authority_id',a.id,'revoked_at',r.revoked_at);
end$$;
revoke all on function public.revoke_signature_signer_authority_v1(uuid,text,uuid)from public,anon,authenticated,service_role;grant execute on function public.revoke_signature_signer_authority_v1(uuid,text,uuid)to authenticated;
